/**
 * sw.js
 * ------
 * Hand-rolled, not generated by Workbox/vite-plugin-pwa — deliberately,
 * to avoid pulling in another heavy dependency tree after this project's
 * earlier install-time pain (see UNDERSTANDING.md's onnxruntime-node
 * saga). Plain JS, registered directly as a static file — no build-time
 * integration needed.
 *
 * SCOPE — what this DOES cache:
 *   - The app shell: HTML, JS, CSS, icons, manifest, favicon.
 *   - The self-hosted MediaPipe model (/models/face_landmarker.task) —
 *     same-origin, and genuinely worth caching for offline use.
 *
 * SCOPE — what this deliberately DOES NOT touch:
 *   - Whisper's model weights (huggingface.co) and the ONNX/MediaPipe
 *     WASM runtime (cdn.jsdelivr.net) — both cross-origin, and both
 *     already managed by Transformers.js / onnxruntime-web's own use of
 *     the Cache Storage API internally (see UNDERSTANDING.md §4).
 *     Intercepting and re-caching those here would be redundant at best
 *     and could conflict with their own cache-key/versioning logic at
 *     worst. This service worker explicitly ignores any cross-origin
 *     request and lets it pass straight through.
 *
 * Manual step on every deploy: bump CACHE_VERSION below. Without an
 * auto-generated build manifest (which is what vite-plugin-pwa would
 * have provided), there's no automatic way to know when cached app-shell
 * files are stale — this is the explicit tradeoff of hand-rolling this
 * instead of using that tooling.
 */

const CACHE_VERSION = "orato-shell-v5";

const SHELL_ASSETS = [
  "/index.html",
  "/manifest.json",
  "/favicon.svg",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/icon-maskable-512.png",
  "/icons/apple-touch-icon.png",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE_VERSION)
      .then((cache) => cache.addAll(SHELL_ASSETS))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key !== CACHE_VERSION).map((key) => caches.delete(key)))
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Only ever handle GET — POST/etc. should never be served from cache.
  if (request.method !== "GET") return;

  // Deliberately hands off anything cross-origin (Whisper weights, the
  // WASM CDN) untouched — see file-level comment above for why.
  if (url.origin !== self.location.origin) return;

  // SPA navigation fallback: always serve the cached app shell for a
  // navigation request, regardless of the specific path, so a bookmarked
  // deep link (e.g. /practice) still loads offline and lets React Router
  // take over client-side. Network-first so online visitors always get
  // the freshest shell; cache is the offline fallback only.
  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(CACHE_VERSION).then((cache) => cache.put("/index.html", copy));
          return response;
        })
        .catch(() => caches.match("/index.html"))
    );
    return;
  }

  // Everything else same-origin (hashed JS/CSS bundles, the MediaPipe
  // model, images): cache-first, populated lazily on first real fetch
  // rather than precached by exact hash (which would need build-time
  // manifest generation this hand-rolled approach doesn't have).
  event.respondWith(
    caches.match(request).then((cached) => {
      if (cached) return cached;
      return fetch(request).then((response) => {
        if (response.ok) {
          const copy = response.clone();
          caches.open(CACHE_VERSION).then((cache) => cache.put(request, copy));
        }
        return response;
      });
    })
  );
});
